//! The state bridge: one walk of a Game, written by the skeleton's program from the same tables as types.rs. Never edited by hand. tools/blitz/export.ts walks the same order over the TypeScript game.
#![allow(unused_imports, unused_variables, unused_mut, clippy::all)]
use crate::{ids::*, js::*, Quat, V3};
use alloc::{string::String, vec::Vec};

#[cold] fn refused(name: &str, ix: usize, n: usize) -> ! { panic!("a {} from outside the game names row {}, and its table holds {}", name, ix, n) }
pub struct W { pub b: Vec<u8>, /** the filtered export: the fields only the harness reads go too (puppet.rs, PuppetMemo.wide) */ pub wide: bool }
impl W { pub fn new() -> Self { W { b: Vec::new(), wide: false } } }
pub struct R<'a> { pub b: &'a [u8], pub p: usize, /** AN ID FROM OUTSIDE IS MEASURED: each table's length, by the ID's name (a call, a question, a write) */ pub known: Option<&'a [(&'static str, usize)]>, /** …or, where the tables are read in the same bytes, the largest of each kind seen, for after (an import) */ pub most: Option<Vec<(&'static str, usize)>> }
impl<'a> R<'a> { pub fn new(b: &'a [u8]) -> Self { R { b, p: 0, known: None, most: None } }
    /// reading what a caller outside the game sent: an ID past its table is refused here, by name, and goes no further into the game
    pub fn measured(b: &'a [u8], known: &'a [(&'static str, usize)]) -> Self { R { b, p: 0, known: Some(known), most: None } }
    /// reading a whole game: `refuse_past` says afterwards whether an ID in it named a row its tables do not hold
    pub fn tallied(b: &'a [u8]) -> Self { R { b, p: 0, known: None, most: Some(Vec::new()) } }
    #[inline] fn id_from_outside(&mut self, name: &'static str, ix: usize) {
        if let Some(k) = self.known { if let Some(&(_, n)) = k.iter().find(|e| e.0 == name) { if ix >= n { refused(name, ix, n); } } }
        else if let Some(m) = self.most.as_mut() { match m.iter_mut().find(|e| e.0 == name) { Some(e) => if ix > e.1 { e.1 = ix; }, None => m.push((name, ix)) } }
    }
    /// the end of a whole game's bytes: every ID against the tables they brought
    pub fn refuse_past(&self, known: &[(&'static str, usize)]) { for &(name, most) in self.most.iter().flatten() { if let Some(&(_, n)) = known.iter().find(|e| e.0 == name) { if most >= n { refused(name, most, n); } } } }
    pub fn take(&mut self, n: usize) -> &'a [u8] { let s = &self.b[self.p..self.p + n]; self.p += n; s } }
pub trait Io: Sized { fn w(&self, o: &mut W); fn r(i: &mut R) -> Self; /** read over what stands here: what the walk does not carry stays as it was */ fn ri(&mut self, i: &mut R) { *self = Self::r(i); } }
macro_rules! num { ($($t:ty),*) => { $( impl Io for $t { #[inline] fn w(&self, o: &mut W) { o.b.extend_from_slice(&self.to_le_bytes()); } #[inline] fn r(i: &mut R) -> Self { let mut a = [0u8; core::mem::size_of::<$t>()]; a.copy_from_slice(i.take(core::mem::size_of::<$t>())); <$t>::from_le_bytes(a) } } )* } }
num!(f64, f32, u8, i8, u16, i16, u32, i32, u64, i64);
impl Io for usize { fn w(&self, o: &mut W) { (*self as u32).w(o) } fn r(i: &mut R) -> Self { u32::r(i) as usize } }
impl Io for bool { fn w(&self, o: &mut W) { o.b.push(*self as u8) } fn r(i: &mut R) -> Self { u8::r(i) != 0 } }
impl Io for () { fn w(&self, _: &mut W) {} fn r(_: &mut R) -> Self {} }
impl Io for &'static str { fn w(&self, o: &mut W) { (self.len() as u32).w(o); o.b.extend_from_slice(self.as_bytes()); } fn r(i: &mut R) -> Self { let n = u32::r(i) as usize; alloc::boxed::Box::leak(String::from(core::str::from_utf8(i.take(n)).unwrap()).into_boxed_str()) } }
impl Io for String { fn w(&self, o: &mut W) { (self.len() as u32).w(o); o.b.extend_from_slice(self.as_bytes()); } fn r(i: &mut R) -> Self { let n = u32::r(i) as usize; String::from(core::str::from_utf8(i.take(n)).unwrap()) } }
impl<T: Io> Io for Option<T> { fn w(&self, o: &mut W) { match self { None => o.b.push(0), Some(x) => { o.b.push(1); x.w(o) } } } fn r(i: &mut R) -> Self { if u8::r(i) == 0 { None } else { Some(T::r(i)) } } fn ri(&mut self, i: &mut R) { if u8::r(i) == 0 { *self = None; } else if let Some(x) = self { x.ri(i); } else { *self = Some(T::r(i)); } } }
impl<T: Io> Io for Vec<T> { fn w(&self, o: &mut W) { (self.len() as u32).w(o); for x in self { x.w(o) } } fn r(i: &mut R) -> Self { let n = u32::r(i) as usize; let mut v = Vec::with_capacity(n); for _ in 0..n { v.push(T::r(i)) } v } fn ri(&mut self, i: &mut R) { let n = u32::r(i) as usize; self.truncate(n); for k in 0..n { if k < self.len() { self[k].ri(i); } else { self.push(T::r(i)); } } } }
impl<T: Io> Io for alloc::boxed::Box<T> { fn w(&self, o: &mut W) { (**self).w(o) } fn r(i: &mut R) -> Self { alloc::boxed::Box::new(T::r(i)) } fn ri(&mut self, i: &mut R) { (**self).ri(i) } }
impl<T: Io, const N: usize> Io for [T; N] { fn w(&self, o: &mut W) { for x in self { x.w(o) } } fn r(i: &mut R) -> Self { core::array::from_fn(|_| T::r(i)) } fn ri(&mut self, i: &mut R) { for x in self.iter_mut() { x.ri(i) } } }
impl<A: Io, B: Io> Io for (A, B) { fn w(&self, o: &mut W) { self.0.w(o); self.1.w(o) } fn r(i: &mut R) -> Self { let a = A::r(i); (a, B::r(i)) } }
impl<A: Io, B: Io, C: Io> Io for (A, B, C) { fn w(&self, o: &mut W) { self.0.w(o); self.1.w(o); self.2.w(o) } fn r(i: &mut R) -> Self { let a = A::r(i); let b = B::r(i); (a, b, C::r(i)) } }
impl<A: Io, B: Io, C: Io, D: Io> Io for (A, B, C, D) { fn w(&self, o: &mut W) { self.0.w(o); self.1.w(o); self.2.w(o); self.3.w(o) } fn r(i: &mut R) -> Self { let a = A::r(i); let b = B::r(i); let c = C::r(i); (a, b, c, D::r(i)) } }
impl<K: Io + Ord + Clone, V: Io> Io for JsMap<K, V> { fn w(&self, o: &mut W) { (self.len() as u32).w(o); for (k, v) in self.iter() { k.w(o); v.w(o) } } fn r(i: &mut R) -> Self { let n = u32::r(i) as usize; let mut m = JsMap::new(); for _ in 0..n { let k = K::r(i); let v = V::r(i); m.set(k, v); } m } fn ri(&mut self, i: &mut R) { let n = u32::r(i) as usize; let mut m = JsMap::new(); let mut old = core::mem::take(self); for _ in 0..n { let k = K::r(i); let mut v = old.delete(k.clone()); match v.as_mut() { Some(x) => x.ri(i), None => v = Some(V::r(i)) } m.set(k, v.unwrap()); } *self = m; } }
impl<K: Io + Ord + Clone> Io for JsSet<K> { fn w(&self, o: &mut W) { (self.len() as u32).w(o); for k in self.iter() { k.w(o) } } fn r(i: &mut R) -> Self { let n = u32::r(i) as usize; let mut m = JsSet::new(); for _ in 0..n { m.add(K::r(i)); } m } }
impl<I: Id, T: Io> Io for Tab<I, T> { fn w(&self, o: &mut W) { (self.len() as u32).w(o); for (_, x) in self.iter() { x.w(o) } } fn r(i: &mut R) -> Self { let n = u32::r(i) as usize; let mut t = Tab::new(); for _ in 0..n { t.push(T::r(i)); } t } fn ri(&mut self, i: &mut R) { let n = u32::r(i) as usize; for k in 0..n { if k < self.len() { self[I::from_ix(k)].ri(i); } else { self.push(T::r(i)); } } } }
impl Io for crate::Num { fn w(&self, o: &mut W) { self.0.w(o) } fn r(i: &mut R) -> Self { crate::Num(f64::r(i)) } }
impl Io for crate::ObjKey { fn w(&self, o: &mut W) { self.0.w(o) } fn r(i: &mut R) -> Self { crate::ObjKey(u32::r(i)) } }

/// one field reached from here, then its value (io::poke, bridge/poke.ts). A value with no fields of its own is written whole
pub trait Poke: Io { fn poke(&mut self, i: &mut R) { self.ri(i) } }
macro_rules! leaf { ($($t:ty),*) => { $( impl Poke for $t {} )* } }
leaf!(f64, f32, u8, i8, u16, i16, u32, i32, u64, i64, usize, bool, (), &'static str, String, crate::Num, crate::ObjKey);
impl<T: Poke> Poke for Option<T> { fn poke(&mut self, i: &mut R) { if u8::r(i) == 0 { self.ri(i) } else { self.as_mut().expect("bridge: a write into a None").poke(i) } } }
impl<T: Poke> Poke for Vec<T> { fn poke(&mut self, i: &mut R) { let k = u32::r(i); if k == 0xffffffff { self.ri(i) } else { self[k as usize].poke(i) } } }
impl<T: Poke> Poke for alloc::boxed::Box<T> { fn poke(&mut self, i: &mut R) { (**self).poke(i) } }
impl<T: Poke, const N: usize> Poke for [T; N] { fn poke(&mut self, i: &mut R) { let k = u32::r(i); if k == 0xffffffff { self.ri(i) } else { self[k as usize].poke(i) } } }
impl<A: Io, B: Io> Poke for (A, B) {}
impl<A: Io, B: Io, C: Io> Poke for (A, B, C) {}
impl<A: Io, B: Io, C: Io, D: Io> Poke for (A, B, C, D) {}
impl<K: Io + Ord + Clone, V: Poke> Poke for JsMap<K, V> { fn poke(&mut self, i: &mut R) { if u8::r(i) == 0 { self.ri(i) } else { let k = K::r(i); self.get_mut(k).expect("bridge: a write into a map at no such key").poke(i) } } }
impl<K: Io + Ord + Clone> Poke for JsSet<K> {}
macro_rules! ids { ($($t:ident),*) => { $( impl Io for $t { fn w(&self, o: &mut W) { (self.ix() as u32).w(o) } fn r(i: &mut R) -> Self { let ix = u32::r(i) as usize; i.id_from_outside(<$t as Id>::NAME, ix); <$t as Id>::from_ix(ix) } } )* } }
ids!(BoxId, FrameBoxId, ClipId, AnimGltfMeshDataId, AnimGltfCastVariantId, AnimGltfCastInfoId, RigId, PoseSetId, RagdollId, CharId, DoorId, SlabRowId, DriveColsId, PropId, InputId, CameraId, ItemId, GuardId, PlayerId, DebrisChunkId, SeatId, LightId, FixtureId, CameraRtId, LaserRtId, WallbreakBreakableId, FurnblastMemberId, WindWindSourceId, DoorOpId, OrdersAssignmentId, DoortoolsRoomSearchId, WordId, DoorGateId, DoortoolsKnownThreatId, ChargeId, OrdersOrderDefId, RoomfightDefId, RoomfightRoomId, CoverOpeningId, WallreactBreachId, TacticsRoleId, TacticsPlanId, TacticsDangerRecId, LanesLaneId, PressureManId, StickyCamId, RescueflowRegionId, RoomClearId, DirectorRunId, RoomfightOpId, WallOpId, WallChargeId, RouteId, EnemysquadsSquadId, DirectorLiveBeatId, GuardsStandoffId, CivId, GameTalkId, FirearmId);
/// on the wire a box of either kind is one number: a world box's row twice over, a frame box's row twice over and one more (the page's book reads it the same way, tools/blitz/export.ts `mixes`)
impl Io for AnyBoxId { fn w(&self, o: &mut W) { (match *self { AnyBoxId::World(b) => 2 * b.ix() as u32, AnyBoxId::Frame(b) => 2 * b.ix() as u32 + 1 }).w(o) } fn r(i: &mut R) -> Self { let v = u32::r(i); let ix = (v / 2) as usize; if v & 1 == 0 { i.id_from_outside(<BoxId as Id>::NAME, ix); AnyBoxId::World(<BoxId as Id>::from_ix(ix)) } else { i.id_from_outside(<FrameBoxId as Id>::NAME, ix); AnyBoxId::Frame(<FrameBoxId as Id>::from_ix(ix)) } } }
leaf!(BoxId, FrameBoxId, AnyBoxId, ClipId, AnimGltfMeshDataId, AnimGltfCastVariantId, AnimGltfCastInfoId, RigId, PoseSetId, RagdollId, CharId, DoorId, SlabRowId, DriveColsId, PropId, InputId, CameraId, ItemId, GuardId, PlayerId, DebrisChunkId, SeatId, LightId, FixtureId, CameraRtId, LaserRtId, WallbreakBreakableId, FurnblastMemberId, WindWindSourceId, DoorOpId, OrdersAssignmentId, DoortoolsRoomSearchId, WordId, DoorGateId, DoortoolsKnownThreatId, ChargeId, OrdersOrderDefId, RoomfightDefId, RoomfightRoomId, CoverOpeningId, WallreactBreachId, TacticsRoleId, TacticsPlanId, TacticsDangerRecId, LanesLaneId, PressureManId, StickyCamId, RescueflowRegionId, RoomClearId, DirectorRunId, RoomfightOpId, WallOpId, WallChargeId, RouteId, EnemysquadsSquadId, DirectorLiveBeatId, GuardsStandoffId, CivId, GameTalkId, FirearmId);

