/// WRITE ONE CARRIED FIELD OF THE GAME FROM OUTSIDE THE TICK (bridge/poke.ts writes the bytes): which table and row, or none for the Game; then the way down by the schema, field by field; then the value
pub fn poke(g: &mut crate::game::Game, b: &[u8]) { let known = crate::id_tables::id_tables(g); let mut i = R::measured(b, &known); let t = u32::r(&mut i); if t == 0xffffffff { g.poke(&mut i); } else { let r = u32::r(&mut i) as usize; match t {
    0 => g.tab.boxes[<BoxId as Id>::from_ix(r)].poke(&mut i),
    1 => g.tab.clip[<ClipId as Id>::from_ix(r)].poke(&mut i),
    2 => g.tab.anim_gltf_mesh_data[<AnimGltfMeshDataId as Id>::from_ix(r)].poke(&mut i),
    3 => g.tab.anim_gltf_cast_variant[<AnimGltfCastVariantId as Id>::from_ix(r)].poke(&mut i),
    4 => g.tab.anim_gltf_cast_info[<AnimGltfCastInfoId as Id>::from_ix(r)].poke(&mut i),
    5 => g.tab.rig[<RigId as Id>::from_ix(r)].poke(&mut i),
    6 => g.tab.pose_set[<PoseSetId as Id>::from_ix(r)].poke(&mut i),
    7 => g.tab.ragdoll[<RagdollId as Id>::from_ix(r)].poke(&mut i),
    8 => g.ch[<CharId as Id>::from_ix(r)].poke(&mut i),
    9 => g.dr[<DoorId as Id>::from_ix(r)].poke(&mut i),
    10 => g.tab.props_prop[<PropId as Id>::from_ix(r)].poke(&mut i),
    11 => g.tab.input[<InputId as Id>::from_ix(r)].poke(&mut i),
    12 => g.tab.camera[<CameraId as Id>::from_ix(r)].poke(&mut i),
    13 => g.tab.item[<ItemId as Id>::from_ix(r)].poke(&mut i),
    14 => g.gd[<GuardId as Id>::from_ix(r)].poke(&mut i),
    15 => g.pl[<PlayerId as Id>::from_ix(r)].poke(&mut i),
    16 => g.tab.debris_chunk[<DebrisChunkId as Id>::from_ix(r)].poke(&mut i),
    17 => g.tab.cmd_seat[<SeatId as Id>::from_ix(r)].poke(&mut i),
    18 => g.tab.light[<LightId as Id>::from_ix(r)].poke(&mut i),
    19 => g.tab.sim_lightshome_fixture[<FixtureId as Id>::from_ix(r)].poke(&mut i),
    20 => g.tab.devices_camera_rt[<CameraRtId as Id>::from_ix(r)].poke(&mut i),
    21 => g.tab.devices_laser_rt[<LaserRtId as Id>::from_ix(r)].poke(&mut i),
    22 => g.tab.wallbreak_breakable[<WallbreakBreakableId as Id>::from_ix(r)].poke(&mut i),
    23 => g.tab.furnblast_member[<FurnblastMemberId as Id>::from_ix(r)].poke(&mut i),
    24 => g.tab.wind_wind_source[<WindWindSourceId as Id>::from_ix(r)].poke(&mut i),
    25 => g.tab.doortools_door_op[<DoorOpId as Id>::from_ix(r)].poke(&mut i),
    26 => g.tab.orders_assignment[<OrdersAssignmentId as Id>::from_ix(r)].poke(&mut i),
    27 => g.tab.doortools_room_search[<DoortoolsRoomSearchId as Id>::from_ix(r)].poke(&mut i),
    28 => g.tab.doortools_word[<WordId as Id>::from_ix(r)].poke(&mut i),
    29 => g.tab.doortools_door_gate[<DoorGateId as Id>::from_ix(r)].poke(&mut i),
    30 => g.tab.doortools_known_threat[<DoortoolsKnownThreatId as Id>::from_ix(r)].poke(&mut i),
    31 => g.tab.doortools_set_charge[<ChargeId as Id>::from_ix(r)].poke(&mut i),
    32 => g.tab.orders_order_def[<OrdersOrderDefId as Id>::from_ix(r)].poke(&mut i),
    33 => g.tab.roomfight_def[<RoomfightDefId as Id>::from_ix(r)].poke(&mut i),
    34 => g.tab.roomfight_room[<RoomfightRoomId as Id>::from_ix(r)].poke(&mut i),
    35 => g.tab.cover_opening[<CoverOpeningId as Id>::from_ix(r)].poke(&mut i),
    36 => g.tab.wallreact_breach[<WallreactBreachId as Id>::from_ix(r)].poke(&mut i),
    37 => g.tab.tactics_role[<TacticsRoleId as Id>::from_ix(r)].poke(&mut i),
    38 => g.tab.tactics_plan[<TacticsPlanId as Id>::from_ix(r)].poke(&mut i),
    39 => g.tab.tactics_danger_rec[<TacticsDangerRecId as Id>::from_ix(r)].poke(&mut i),
    40 => g.tab.lanes_lane[<LanesLaneId as Id>::from_ix(r)].poke(&mut i),
    41 => g.tab.pressure_man[<PressureManId as Id>::from_ix(r)].poke(&mut i),
    42 => g.tab.stickycam_sticky_cam[<StickyCamId as Id>::from_ix(r)].poke(&mut i),
    43 => g.tab.rescueflow_region[<RescueflowRegionId as Id>::from_ix(r)].poke(&mut i),
    44 => g.tab.squad_room_clear[<RoomClearId as Id>::from_ix(r)].poke(&mut i),
    45 => g.tab.director_run[<DirectorRunId as Id>::from_ix(r)].poke(&mut i),
    46 => g.tab.roomfight_op[<RoomfightOpId as Id>::from_ix(r)].poke(&mut i),
    47 => g.tab.wallcharge_wall_op[<WallOpId as Id>::from_ix(r)].poke(&mut i),
    48 => g.tab.wallcharge_set_wall_charge[<WallChargeId as Id>::from_ix(r)].poke(&mut i),
    49 => g.tab.route[<RouteId as Id>::from_ix(r)].poke(&mut i),
    50 => g.tab.enemysquads_squad[<EnemysquadsSquadId as Id>::from_ix(r)].poke(&mut i),
    51 => g.tab.director_live_beat[<DirectorLiveBeatId as Id>::from_ix(r)].poke(&mut i),
    52 => g.tab.guards_standoff[<GuardsStandoffId as Id>::from_ix(r)].poke(&mut i),
    53 => g.cv[<CivId as Id>::from_ix(r)].poke(&mut i),
    54 => g.tab.game_talk[<GameTalkId as Id>::from_ix(r)].poke(&mut i),
    55 => g.fa[<FirearmId as Id>::from_ix(r)].poke(&mut i),
    56 => g.tab.frame_boxes[<FrameBoxId as Id>::from_ix(r)].poke(&mut i),
    k => panic!("bridge: no table {}", k) } } assert!(i.p == b.len(), "bridge: {} bytes left over in a write", b.len() - i.p); }

/// a game as bytes: Game's plain fields, then every table in a fixed order, then the serial counter
pub fn export(g: &crate::game::Game) -> Vec<u8> { let mut o = W::new(); g.w(&mut o);
    g.tab.boxes.w(&mut o);
    g.tab.clip.w(&mut o);
    g.tab.anim_gltf_mesh_data.w(&mut o);
    g.tab.anim_gltf_cast_variant.w(&mut o);
    g.tab.anim_gltf_cast_info.w(&mut o);
    g.tab.rig.w(&mut o);
    g.tab.pose_set.w(&mut o);
    g.tab.ragdoll.w(&mut o);
    g.ch.w(&mut o);
    g.dr.w(&mut o);
    g.tab.props_prop.w(&mut o);
    g.tab.input.w(&mut o);
    g.tab.camera.w(&mut o);
    g.tab.item.w(&mut o);
    g.gd.w(&mut o);
    g.pl.w(&mut o);
    g.tab.debris_chunk.w(&mut o);
    g.tab.cmd_seat.w(&mut o);
    g.tab.light.w(&mut o);
    g.tab.sim_lightshome_fixture.w(&mut o);
    g.tab.devices_camera_rt.w(&mut o);
    g.tab.devices_laser_rt.w(&mut o);
    g.tab.wallbreak_breakable.w(&mut o);
    g.tab.furnblast_member.w(&mut o);
    g.tab.wind_wind_source.w(&mut o);
    g.tab.doortools_door_op.w(&mut o);
    g.tab.orders_assignment.w(&mut o);
    g.tab.doortools_room_search.w(&mut o);
    g.tab.doortools_word.w(&mut o);
    g.tab.doortools_door_gate.w(&mut o);
    g.tab.doortools_known_threat.w(&mut o);
    g.tab.doortools_set_charge.w(&mut o);
    g.tab.orders_order_def.w(&mut o);
    g.tab.roomfight_def.w(&mut o);
    g.tab.roomfight_room.w(&mut o);
    g.tab.cover_opening.w(&mut o);
    g.tab.wallreact_breach.w(&mut o);
    g.tab.tactics_role.w(&mut o);
    g.tab.tactics_plan.w(&mut o);
    g.tab.tactics_danger_rec.w(&mut o);
    g.tab.lanes_lane.w(&mut o);
    g.tab.pressure_man.w(&mut o);
    g.tab.stickycam_sticky_cam.w(&mut o);
    g.tab.rescueflow_region.w(&mut o);
    g.tab.squad_room_clear.w(&mut o);
    g.tab.director_run.w(&mut o);
    g.tab.roomfight_op.w(&mut o);
    g.tab.wallcharge_wall_op.w(&mut o);
    g.tab.wallcharge_set_wall_charge.w(&mut o);
    g.tab.route.w(&mut o);
    g.tab.enemysquads_squad.w(&mut o);
    g.tab.director_live_beat.w(&mut o);
    g.tab.guards_standoff.w(&mut o);
    g.cv.w(&mut o);
    g.tab.game_talk.w(&mut o);
    g.fa.w(&mut o);
    g.tab.frame_boxes.w(&mut o);
    g.serial_next.w(&mut o); g.loose_poses.w(&mut o); o.b }

impl Io for crate::anim_skeleton::LoosePose { fn w(&self, o: &mut W) { self.nodes.w(o); self.floats.w(o); } fn r(i: &mut R) -> Self { let nodes = u32::r(i); Self { nodes, floats: Io::r(i) } } }

/// A STATE EXPORTED IN THE MIDDLE OF A LEVEL SCRIPT CANNOT BE IMPORTED: a JavaScript generator's place and locals cannot be read, so the beat's frame was not carried, and standing at Spent it would end at once. Refused by name
pub fn refuse_mid_script(g: &crate::game::Game) {
    for id in g.tab.director_live_beat.ids().collect::<Vec<_>>() {
        let b = &g.tab.director_live_beat[id];
        if b.state == crate::director::BeatState::Running && matches!(b.it, crate::director::BeatFrame::Spent) { panic!("bridge: this state was exported in the middle of a level script (the beat '{}' is running): a generator's place cannot be carried. Compare a tutorial from before its program starts", b.name); }
    }
}

/// WHAT THE HOST HANDS THE GAME BEFORE EACH STEP, as its own small buffer (bridge/export.ts hostHalf): each seat's record, then every camera and Input row, then each seat's mark (the cut the host last took: Seat.takeCut is the host's). A row that is a seat's is the game's own and stays;
/// the rest are the host's and are taken. A row with no row here is left out. Answers the records in seat order, for `game_step_seats`. Nothing else of the game moves.
pub fn take_host_half(g: &mut crate::game::Game, b: &[u8]) -> Vec<crate::cmd::PlayerCmd> {
    let mut r = R::new(b);
    let n = u32::r(&mut r) as usize; assert!(n == g.seats.len(), "bridge: {} record(s) for {} seat(s)", n, g.seats.len());
    let cmds: Vec<crate::cmd::PlayerCmd> = (0..n).map(|_| Io::r(&mut r)).collect();
    let nc = u32::r(&mut r) as usize; let cams: Vec<crate::camera::FollowCamera> = (0..nc).map(|_| Io::r(&mut r)).collect();
    let ni = u32::r(&mut r) as usize; let ins: Vec<crate::input::Input> = (0..ni).map(|_| Io::r(&mut r)).collect();
    let ns = u32::r(&mut r) as usize; let marks: Vec<u32> = (0..ns).map(|_| u32::r(&mut r)).collect();
    // which of the host's objects exist (the tick asks only that, and of the particle pool its two switches): bit 0 a pool, bit 1 a reach keeper, bit 2 its particles collide, bit 3 its sparks bounce
    let has = u32::r(&mut r);
    if has & 1 != 0 { let p = g.engine.particles.get_or_insert_with(crate::render_particles::Particles::blank); p.collide = has & 4 != 0; p.spark_bounce = has & 8 != 0; } else { g.engine.particles = None; }
    if has & 2 != 0 { if g.engine.reach.is_none() { g.engine.reach = Some(crate::render_reach_keep::ReachKeep::blank()); } } else { g.engine.reach = None; }
    for s in g.tab.cmd_seat.ids().collect::<Vec<_>>() { if s.ix() < marks.len() { g.tab.cmd_seat[s].mark = marks[s.ix()]; } }
    assert!(r.p == b.len(), "bridge: {} bytes left over in the host's half", b.len() - r.p);
    let seats: Vec<CameraId> = g.seats.iter().map(|s| g.tab.cmd_seat[*s].cam).collect();
    for c in g.tab.camera.ids().collect::<Vec<_>>() { if !seats.contains(&c) && c.ix() < cams.len() { g.tab.camera[c] = cams[c.ix()].clone(); } }
    let inputs: Vec<InputId> = g.seats.iter().map(|s| g.tab.cmd_seat[*s].input).collect();
    for i in g.tab.input.ids().collect::<Vec<_>>() { if !inputs.contains(&i) && i.ix() < ins.len() { g.tab.input[i] = ins[i.ix()].clone(); } }
    let me = g.local_seat.and_then(|l| g.seats.iter().position(|s| *s == l)).unwrap_or(0);
    g.cmd_buf = cmds.get(me).cloned();
    cmds
}

/// WHICH OF rust/sim'S SLOTS THIS GAME STANDS IN. The one way to change it, because two fields hold it: `g.sim` and the box mirror's `slot`, which the mirror keeps as the TypeScript's does and the world's lookups read.
pub fn set_slot(g: &mut crate::game::Game, slot: usize) { g.sim = slot; g.col.mirror.slot = slot as f64; }

pub fn stats_as_counted(g: &crate::game::Game) -> crate::game::Stats { let mut s = g.stats.clone(); let h = &g.m.glassbreak.gb_host; let t = unsafe { core::ptr::addr_of!(::sim::panes::TALLY).read() }; let q = &mut s.glassbreak; q.panes = (h.panes + t.panes) as i32; q.impacts = (h.impacts + t.impacts) as i32; q.sites = (h.sites + t.sites) as i32; q.runs = (h.runs + t.runs) as i32; q.dropped = (h.dropped + t.dropped) as i32; q.shards = h.shards as i32; q.chips = h.chips as i32; q.refused = h.refused as i32; q.diced = (h.diced + t.diced) as i32; q.clumps = (h.clumps + t.clumps) as i32; q.sheets = (h.sheets + t.sheets) as i32; q.blasts = (h.blasts + t.blasts) as i32; q.thinks = (h.thinks + t.thinks) as i32; q.hooked = h.hooked as i32; q.raked = (h.raked + t.raked) as i32; s }


impl Io for crate::Opaque { fn w(&self, _: &mut W) {} fn r(_: &mut R) -> Self { crate::Opaque } }
// AN ADDRESS'S WORDS ARE NOT ON THE WIRE: the table declares the `URLSearchParams` arm of a `string | URLSearchParams` argument as holding nothing
// (tools/blitz/schema.json), and the TypeScript writes nothing for it. A host that has an address hands its TEXT across (the `Text` arm) and the
// game reads the words itself (query.rs). Words that came or went this way would be an address with no words in it, read without a sign: the
// mission not started, the fog off, and nothing said. So both ends stop, by name.
impl Io for crate::query::Query {
    fn w(&self, _: &mut W) { panic!("an address's words are not on the wire: hand the address's text across (the Text arm)") }
    fn r(_: &mut R) -> Self { panic!("an address's words are not on the wire: hand the address's text across (the Text arm)") }
}
impl Poke for crate::Opaque {}
